import{_ as l,l as o,o as a,c as n,v as t,p as i,x as r,d as h,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Seq2Seq 编码解码","description":"","frontmatter":{"title":"Seq2Seq 编码解码","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/seq2seq-encode-decode.md","filePath":"llm/seq2seq-encode-decode.md","lastUpdated":1789023840000}'),m={name:"llm/seq2seq-encode-decode.md"};function _(p,e,q,u,E,S){const s=o("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="seq2seq-编码解码" tabindex="-1">Seq2Seq 编码解码 <a class="header-anchor" href="#seq2seq-编码解码" aria-label="Permalink to &quot;Seq2Seq 编码解码&quot;">​</a></h1><div class="epigraph"><p>一个循环网把源序列压成定长向量，另一个循环网把它展开成目标序列；两端长度可以不同，中间却只有那一个向量。</p><footer>—— 据 Sutskever, Vinyals &amp; Le, Sequence to Sequence Learning with Neural Networks, NeurIPS 2014；Cho et al., EMNLP 2014 整理</footer></div><p><a href="/llm/gru-vs-lstm">GRU 对照</a>给出可训的门控递推。本课不比较门的个数。缺口是：翻译、摘要要把一条序列映成<strong>另一条</strong>序列，长度不必相等，也不能逐步要求源与目标对齐在同一 \\(t\\)。方法是编码器—解码器：编码器读完源，交出最终状态（或若干层的最终状态）；解码器以之为初值，按下一词分类吐出目标。Teacher forcing 与注意力是后课；本课先把瓶颈暴露出来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>语言模型的条件是目标自己的前缀。跨语言时，条件应是另一条符号串。若强行把源与目标拼成一条再做语言模型，分界与长度会纠缠，且源侧没有「读完再写」的阶段。缺口是两个循环角色：编码器只读源，不预测目标词；解码器只写目标，每步的输入是已写出的目标符号（训练时可以是真值，下一课）。交接物是固定维向量 \\(s\\)，通常取编码器最后一步的 \\(h_n\\)。</p><p>\\(s\\) 必须承载整句信息。源一长，\\(n\\) 步压缩进固定 \\(d\\) 维，就是信息瓶颈。Sutskever 等人用大 LSTM 与倒序源缓解，但几何上瓶颈仍在。本课把这个「单一向量交接」写成定义，以便注意力课有明确要拆的对象。</p><h3 id="编码器不是自编码器里的重构" tabindex="-1">编码器不是自编码器里的重构 <a class="header-anchor" href="#编码器不是自编码器里的重构" aria-label="Permalink to &quot;编码器不是自编码器里的重构&quot;">​</a></h3><p>Seq2Seq 的损失只在目标符号的下一词交叉熵上，不要求把源重构回来。编码器可以丢掉对翻译无用的源细节。把架构理解成「压缩—解压同一句话」，会误用重构损失，也解释不了源语言与目标语言词表不同。两端可以是不同词表、不同嵌入表，只共享交接向量的维数。</p><p><span class="marginnote">实现：编码器双向时，正向与反向最终状态拼接成 \\(s\\)，解码器初始状态由线性层映回。双向增加的是源侧上下文，不是注意力；解码器仍只看见一个 \\(s\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编码器：\\(h_t^{\\mathrm{enc}}=f_{\\mathrm{enc}}(h_{t-1}^{\\mathrm{enc}},x_t)\\)，\\(s=h_{n}^{\\mathrm{enc}}\\)。解码器：\\(h_t^{\\mathrm{dec}}=f_{\\mathrm{dec}}(h_{t-1}^{\\mathrm{dec}},y_{t-1})\\)，\\(h_0^{\\mathrm{dec}}=s\\)，每步 \\(z_t=\\mathrm{Linear}(h_t^{\\mathrm{dec}})\\) 对目标词表做交叉熵。推理时 \\(y_{t-1}\\) 来自上一步抽样或贪婪；训练时常用真值 \\(y_{t-1}\\)。长度不同完全合法：源 \\(n\\) 与目标 \\(m\\) 只在各自循环里出现。</p>',11)),(a(),i(c,null,{default:r(()=>[d(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20SRC%5B%22%E6%BA%90%E5%BA%8F%E5%88%97%22%5D%20--%3E%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%20RNN%22%5D%0A%20%20ENC%20--%3E%20S%5B%22%E5%AE%9A%E9%95%BF%E5%90%91%E9%87%8F%20s%22%5D%0A%20%20S%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E5%99%A8%20RNN%22%5D%0A%20%20DEC%20--%3E%20TGT%5B%22%E7%9B%AE%E6%A0%87%E8%AF%8D%E5%BA%8F%E5%88%97%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[h(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>变长到变长被拆成「变长到定长」加「定长到变长」。第一段的信息损失不可逆：解码器无法回头问编码器某一个词——它手里只有 \\(s\\)。短句上这够用；长句上 \\(s\\) 被后期源符号覆盖（RNN 的近因偏置），早期对齐线索消失。这不是实现没训好，是接口只允许一次交接。</p><p>倒序源（Sutskever 等人的技巧）让源的句首靠近交接时刻，缓解近因，但不增加 \\(s\\) 的维数，只是重新安排哪些源符号最后写入。多层编码器同样只改变 \\(s\\) 的质量，不改变「只有一个向量」这条。要按目标位置读取不同的源片段，必须留下全体 \\(h_j\\)，那是注意力课。</p><p>计算上仍两次串行循环。相对稍后的注意力，这里的优点是推理时编码器可以丢掉源端全体隐状态，只留 \\(s\\)；缺点正是丢掉了它们。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 teacher forcing 的训练—推理落差，不写对齐。下一课<a href="/llm/teacher-forcing">Teacher forcing</a>专门处理解码器输入用真值还是用自身预测。后课默认：序列到序列的基线是编码解码加定长瓶颈；注意力将针对「只有 \\(s\\)」这一缺口，而不是重写门控。多任务共用一个编码器仍只交出各自的 \\(s\\)，瓶颈形状不变。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>编码器把源压成定长 \\(s\\)，解码器从 \\(s\\) 展开目标，两端长度独立。</li><li>损失只在目标下一词，不是源的重构。</li><li>单一向量交接是长句对齐失败的结构原因。</li><li>双向编码仍只交出一个（拼接后的）\\(s\\)。</li><li>倒序源只改写入次序，不增加交接维数。</li><li>出处：Sutskever et al., NeurIPS 2014；Cho et al., EMNLP 2014。</li></ul>',8))])}const N=l(m,[["render",_]]);export{A as __pageData,N as default};
